items.raw:
\begin{proof}
Suppose that $\pi(\Psi) \cong \pi(\Psi_\xi)$.  In the setting of Lemma~\ref{HMCor}, this means there is some $g \in N_G(T)$ such that $\mathrm{Res}_{T}(\phi_0 \phi_1 \cdots \phi_{d-1})=\mathrm{Res}_{T}{}^g(\xi \phi_0 \phi_1 \cdots \phi_{d-1})$.   
Then ${}^g(\xi\phi_0){}^g\phi_1\cdots {}^g \phi_{d-1}$ is a refactorization of $\phi_0\cdots \phi_{d-1}$, in the sense of \cite[Definition 5.3]{Murnaghan2011}, and so by \cite[Proposition 5.4]{Murnaghan2011}, for each $i>0$, $\prod_{j=i}^d \phi_j$ and $\prod_{j=i}^d {}^g\phi_j$ coincide on $G^i_{x,r_{i-1}+}$.  
The genericity of the characters $\phi_j$ recursively implies, as in the proof of \cite[Proposition 5.6]{Murnaghan2011}, that $g\in G^1$, and so ${}^g\phi_i=\phi_i$ for all $i\geq 1$.
Therefore our equality reduces to $\mathrm{Res}_{T_{r_0}} \phi_0 = \mathrm{Res}_{T_{r_0}} {}^g(\xi\phi_0) =  \mathrm{Res}_{T_{r_0}} {}^g\phi_0$, whence $g\in T$ by genericity.  Returning to the first equality we conclude that $\xi$ is the trivial character of $T$.
\end{proof}

\begin{proof}
The twisted Mackey component ${}^{g^{-1}}\tau(g)$ depends only $\mathrm{Res}_{G_{g^{-1}y}\cap \mathsf{K}}\kappa(\Psi)$.  By Lemma~\ref{L:Murn}, $\kappa(\Psi_\xi)=\overline{\xi}\kappa(\Psi)$; by hypothesis 
$\mathrm{Res}_{G_{g^{-1}y}\cap\mathsf{K}}\overline{\xi}$ is trivial.  
Thus 
$\mathrm{Ind}_{G_y \cap {}^g\mathsf{K}}^{G_y} {}^g\kappa(\Psi)$ is a common component of both $\pi(\Psi)$ and $\pi(\Psi_\xi)$.  By Proposition~\ref{P:inequiv}, $\pi(\Psi)\not\cong\pi(\Psi_\xi)$.  Since these are inequivalent irreducible supercuspidal representations, they have distinct inertial support, and thus no irreducible representation of $G_y$ occurring in $\mathrm{Ind}_{G_y \cap {}^g\mathsf{K}}^{G_y} {}^g\kappa(\Psi)$ can be a type.
\end{proof}

\begin{proof}
Let $\mathcal{F}$ be the facet containing $x$.  We have $\mathsf{K}\subseteq G_x$.  Since $y \in \overline{\mathcal{F}}$ by hypothesis, $G_x \subseteq G_y$.  This implies that $\mathsf{K}\subseteq G_y$, whence the first statement by Proposition~\ref{P:type}.  
\end{proof}


Now, continuing with the notation of the previous section, we identify $g\in G$ for which the associated Mackey components do not contain types.

\begin{proof}
Let $x \in \mathcal{B}(T) \subseteq \mathcal{B}(G)$ and set $\pi=\pi(\Psi)$.  Let  $y\neq y'$ be $G$-conjugate vertices of two distinct alcoves $\mathcal{C}, \mathcal{C}'$ of $\mathcal{B}(G)$ such that $x \in \overline{\mathcal{C}}\cap \overline{\mathcal{C}'}$.  Then for any $s_0>0$, we have that $y,y' \in \overline{\Omega(x,s_0)}$.  Let $g \in G$ be such that $y'=g^{-1}y$.  If both $y$ and $g^{-1}y$ lie in $\mathcal{B}^T$, then by the proof of Theorem~\ref{T:unicity}, we conclude that both $(G_y,\tau(1))$ and $(G_{y},\tau(g))$ are types for $\pi$ occurring in $\mathrm{Res}_{G_y}\pi$.  Note that although these types are induced from the $G$-conjugate types $(\mathsf{K},\kappa)$ and $({}^g\mathsf{K},{}^g\kappa)$, they are not themselves $G$-conjugate since $g\notin N_G(G_y)=G_y$.
Neither are these types isomorphic, since $\pi \cong \textrm{c-}\mathrm{Ind}_{G_y}^G\tau(1)$ implies
$$
\mathbb{C}\cong\mathrm{Hom}_{G}(\pi,\pi) \cong \mathrm{Hom}_{G_y}(\tau(1),\mathrm{Res}_{G_y}\pi)
$$
by Frobenius reciprocity.
\end{proof}

We next prove the existence of pairs $(G,T)$ satisfying the hypotheses of Lemma~\ref{L:strongunicityfails} with an example such that $G$ has rank $2$.  We thank Jeff Adler for providing this instructive example of a torus that stabilizes more than the closure of a single facet.

\begin{example}\label{Ex:1}
Consider $G=\mathrm{Sp}_4(F)$, given in matrix form relative to $J=\left[\begin{smallmatrix}0&I\\-I&0\end{smallmatrix}\right]\in M_4(F)$ 
as the set
$$
G = \{ g \in \mathrm{GL}_4(F)\mid {}^tgJg=J\}
$$
where ${}^tg$ denotes the transpose.  Note that $G$ contains a generalized Levi subgroup $G'$ isomorphic to $\mathrm{SL}_2(F)\times \mathrm{SL}_2(F)$, defined by the long roots.

Let $\varpi$ be a uniformizer of $F$.  For $i=1,2$, we choose an anisotropic torus $T_i$ of $\mathrm{SL}_2(F)$ that isomorphic to the norm-one elements of some quadratic ramified extension $E_i=F[\sqrt{\gamma_i\varpi}]$ with $\nu(\gamma_i)=0$.  Let $T=T_1\times T_2$ be the corresponding anisotropic torus of $G'$; explicitly we embed $T$ into $G$ as the subgroup
$$
T=\left\{ 
\bmat{a &0 &\phantom{b}b\phantom{b}&\phantom{b}0\phantom{b}\\ 
0&c&0&d\\ 
b\gamma_1\varpi &0&a&0\\ 0&d\gamma_2\varpi & 0& c}
\;\; \middle| \;\;\parbox{1.2in}{$a,b,c,d \in {\scriptstyle{\mathcal{O}}}, \quad\quad$ 
$a^2-b^2\gamma_1\varpi = 1$, $c^2-d^2\gamma_2\varpi=1$}\right\}.
$$
For each $i$, the point in the building $\mathcal{B}(\mathrm{SL}_2,F)$ corresponding to $T_i$ is the midpoint of the fundamental alcove.  Thus the point $x$ representing $\mathcal{B}(T)\subset \mathcal{B}(G)$ is the midpoint of the diagonal facet $\mathcal{F}$ in the closure of the fundamental alcove $\mathcal{C}$ in the standard apartment ${\mathcal{A}}$ of $\mathcal{B}(G)$, as illustrated in Figure~\ref{Fig:1}.  Evidently $\overline{\mathcal{F}} \subseteq {\mathcal{A}}^T$.

